#!/usr/bin/env python3
"""validate_lean.py - checks the optik binary against test vectors generated by the Lean models in lean/.

The vectors' expected answers come from the definitions the Lean theorems are about (see lean/APPENDIX_B.md).
  spss.json  string sets and k-mer queries, answered by Spss.occursB, which is proved equal to Spss.Occurs.
             Each set is indexed with build-spss and queried with query --ids, and a k-mer counts as present when its id is not -1.
  dbg.json   read sets and their maximal unitigs under Definition 7.1.
             dbruijn builds each one with --graph table (the walker), --graph part (partitioned compaction) and the Elias-Fano graph.
             OPTIK_DBG_COMPACT=1 selects that last graph, whose keys and ranks the Ef proofs model.
             Every unitig partition must equal the Lean one, which also checks prop:glue on the real code.
  dbg2.json  read sets with a duplicated, partly mutated piece, built with -c 2 in the same three ways.
             A fourth build forces partitioned compaction to spill (OPTIK_SPILL_TEST), writing the solid lists as the Varint proofs model.
             The unitigs must be those over solid k-mers.
             The GFA's edges, each segment's (k+1)-mers plus its links, must be exactly Count.TrimEdge, the observed edges between solid k-mers.
             That checks the edge masks and their trimming.

Usage: python3 bench/validate_lean.py --vectors DIR [--optik PATH] [--json]
The exit status is 0 when every check passes.
"""

import argparse
import json
import os
import subprocess
import sys
import tempfile

from checklog import CheckLog
from config import PATHS
from diagnostics import DETAIL_CHARS
from dna import read_fasta, revcomp, write_fasta

check = CheckLog(detail_on_pass=False)
FAILS = check.failed
# Pass or fail of each named check, printed as JSON with --json for bench/negative_controls.py.
RESULTS = {}


# A spill share this small makes every partition buffer spill, even for a few reads.
SPILL_TEST_BYTES = 64

# name -> (--graph value, extra environment)
GRAPH_MODES = {
    "table": ("table", {}),
    "part": ("part", {}),
    "ef": ("table", {"OPTIK_DBG_COMPACT": "1"}),
}
SOLID_MODES = {**GRAPH_MODES, "spill": ("part", {"OPTIK_SPILL_TEST": str(SPILL_TEST_BYTES)})}


def run(cmd, env=None):
    """Run an optik command, with `env` added to the environment, returning the completed process."""
    return subprocess.run(
        [str(arg) for arg in cmd], capture_output=True, text=True, check=False, env={**os.environ, **(env or {})}
    )


def canonical(kmer):
    """The smaller of a k-mer and its reverse complement, which is also the smaller packed word."""
    return min(kmer, revcomp(kmer))


def unitig_partition(fasta, kmer_len):
    """The unitigs of a FASTA file, each as the set of its canonical k-mers."""
    return {
        frozenset(canonical(seq[i : i + kmer_len]) for i in range(len(seq) - kmer_len + 1))
        for _, seq in read_fasta(fasta)
    }


def check_spss(optik, cases, work):
    """Every Spss query must be answered as Spss.occursB answers it."""
    wrong = []
    for n, case in enumerate(cases):
        kmer_len = case["k"]
        ref, queries, idx, ids = (os.path.join(work, f"s{n}{ext}") for ext in (".fa", ".q.fa", ".spss", ".ids"))
        write_fasta(ref, [(f"s{i}", seq) for i, seq in enumerate(case["strings"])])
        write_fasta(queries, [(f"q{i}", q["kmer"]) for i, q in enumerate(case["queries"])])
        build = run([optik, "build-spss", "-i", ref, "-k", kmer_len, "-o", idx])
        query = run([optik, "query", "-i", idx, "-q", queries, "--ids", ids]) if build.returncode == 0 else build
        if query.returncode != 0:
            wrong.append(f"case {n}: {query.stderr[-DETAIL_CHARS:]}")
            continue
        with open(ids) as handle:
            got = [line.split()[0] != "-1" for line in handle]
        expect = [q["present"] for q in case["queries"]]
        if got != expect:
            wrong.append(f"case {n} (k={kmer_len}): optik {got} vs Lean {expect}")
    check(f"spss: {len(cases)} index/query cases answer as Spss.Occurs", not wrong, "; ".join(wrong[:3]))
    RESULTS["lean_spss_presence"] = {"pass": not wrong}


def check_dbg(optik, cases, work):
    """Every graph builder must return the Lean unitig partition."""
    for mode, (graph, env) in GRAPH_MODES.items():
        wrong = []
        for n, case in enumerate(cases):
            kmer_len = case["k"]
            reads, out = os.path.join(work, f"d{n}.fa"), os.path.join(work, f"d{n}.{mode}.fa")
            write_fasta(reads, [(f"r{i}", seq) for i, seq in enumerate(case["reads"])])
            proc = run([optik, "dbruijn", "-i", reads, "-k", kmer_len, "-c", "1", "--graph", graph, "-t", "2", "-o", out], env)
            if proc.returncode != 0:
                wrong.append(f"case {n}: {proc.stderr[-DETAIL_CHARS:]}")
                continue
            expect = {frozenset(unitig) for unitig in case["unitigs"]}
            got = unitig_partition(out, kmer_len)
            if got != expect:
                wrong.append(f"case {n} (k={kmer_len}): {len(got)} unitigs vs Lean {len(expect)}")
        check(f"dbg {mode}: {len(cases)} read sets give the Lean unitig partition", not wrong, "; ".join(wrong[:3]))
        RESULTS[f"lean_dbg_{mode}"] = {"pass": not wrong}


def gfa_edges(gfa, kmer_len):
    """The canonical (k+1)-mers of a GFA's edges, inside segments and across links."""
    segs, links = {}, []
    with open(gfa) as handle:
        for line in handle:
            fields = line.rstrip("\n").split("\t")
            if fields[0] == "S":
                segs[fields[1]] = fields[2]
            elif fields[0] == "L":
                links.append(fields[1:5])
    edges = {canonical(seq[i : i + kmer_len + 1]) for seq in segs.values() for i in range(len(seq) - kmer_len)}
    oriented = lambda name, sign: segs[name] if sign == "+" else revcomp(segs[name])
    for a, sign_a, b, sign_b in links:
        edges.add(canonical(oriented(a, sign_a)[-kmer_len:] + oriented(b, sign_b)[kmer_len - 1]))
    return edges


def check_dbg_solid(optik, cases, work):
    """At -c 2 every builder must give the unitigs and edges over solid k-mers."""
    for mode, (graph, env) in SOLID_MODES.items():
        wrong_unitigs, wrong_edges = [], []
        for n, case in enumerate(cases):
            kmer_len, min_count = case["k"], case["min_count"]
            reads = os.path.join(work, f"c{n}.fa")
            fasta, gfa = (os.path.join(work, f"c{n}.{mode}{ext}") for ext in (".fa", ".gfa"))
            write_fasta(reads, [(f"r{i}", seq) for i, seq in enumerate(case["reads"])])
            base = [optik, "dbruijn", "-i", reads, "-k", kmer_len, "-c", min_count, "--graph", graph, "-t", "2"]
            base += ["--tmp-dir", work, "-o"]
            procs = [run(base + [fasta], env), run(base + [gfa], env)]
            failed = [proc for proc in procs if proc.returncode != 0]
            if failed:
                wrong_unitigs.append(f"case {n}: {failed[0].stderr[-DETAIL_CHARS:]}")
                continue
            expect = {frozenset(unitig) for unitig in case["unitigs"]}
            got = unitig_partition(fasta, kmer_len)
            if got != expect:
                wrong_unitigs.append(f"case {n} (k={kmer_len}): {len(got)} unitigs vs Lean {len(expect)}")
            got_edges, expect_edges = gfa_edges(gfa, kmer_len), set(case["edges"])
            if got_edges != expect_edges:
                wrong_edges.append(
                    f"case {n} (k={kmer_len}): {len(got_edges - expect_edges)} extra, {len(expect_edges - got_edges)} missing"
                )
        check(
            f"dbg -c 2 {mode}: {len(cases)} read sets give the Lean unitigs over solid k-mers",
            not wrong_unitigs,
            "; ".join(wrong_unitigs[:3]),
        )
        check(
            f"dbg -c 2 {mode}: GFA edges are the observed edges between solid k-mers",
            not wrong_edges,
            "; ".join(wrong_edges[:3]),
        )
        RESULTS[f"lean_dbg_solid_{mode}"] = {"pass": not wrong_unitigs}
        RESULTS[f"lean_dbg_edges_{mode}"] = {"pass": not wrong_edges}


def main():
    """Run every vector check and exit non-zero on any failure."""
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--vectors", required=True)
    parser.add_argument("--optik", default=str(PATHS["optik"]))
    parser.add_argument("--json", action="store_true", help="also print the checks as a JSON report")
    args = parser.parse_args()
    with tempfile.TemporaryDirectory(prefix="optik_lean_") as work:
        with open(os.path.join(args.vectors, "spss.json")) as handle:
            check_spss(args.optik, json.load(handle), work)
        with open(os.path.join(args.vectors, "dbg.json")) as handle:
            check_dbg(args.optik, json.load(handle), work)
        with open(os.path.join(args.vectors, "dbg2.json")) as handle:
            check_dbg_solid(args.optik, json.load(handle), work)
    print(f"validate_lean: {'ALL PASS' if not FAILS else f'{len(FAILS)} FAILURE(S)'}")
    if args.json:
        print(json.dumps({"checks": RESULTS}))
    return 1 if FAILS else 0


if __name__ == "__main__":
    sys.exit(main())
